from rules import amount


def solve(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}

    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue

        if 'id' in event:
            identity = ('id', event['id'])
        else:
            identity = ('anonymous', position)

        revision = event.get('revision', 0)
        current = winners.get(identity)
        if current is None or revision >= current[0]:
            winners[identity] = (revision, position, event)

    balances = dict(data.get('opening', {}))
    for _, _, event in winners.values():
        if event.get('void') is True:
            continue

        account = event.get('account', 'default')
        currency = event.get('currency', 'USD')
        key = f'{account}|{currency}'
        balances[key] = balances.get(key, 0) + amount(event, data['rounding'])

    return {'balances': balances}

def _rounded_division(numerator, denominator, mode):
    if mode == 'floor':
        return numerator // denominator
    if mode == 'half_up':
        return (numerator + denominator // 2) // denominator
    raise ValueError(f'unsupported rounding mode: {mode}')


def amount(event, mode):
    base = event['price'] * event.get('quantity', 1)
    discount_bp = min(10000, max(0, event.get('discount_bp', 0)))
    net = _rounded_division(base * (10000 - discount_bp), 10000, mode)

    tax_bp = event.get('tax_bp', 0)
    tax = _rounded_division(net * tax_bp, 10000, mode)
    total = net + tax

    if event.get('kind') == 'refund':
        total = -total
    return total
